		ident2[l] = '\0';
		execBlock = !strcasecmp(ident2, "BLOCK");
		passAsIs = 0;
	}
	else
	{
		/* Named parameters must be processed in the INSERT, UPDATE, DELETE, MERGE statements. */
		/* If CTEs are present in the query, they begin with the WITH keyword. */
		passAsIs = strcasecmp(ident, "INSERT") && strcasecmp(ident, "UPDATE") &&
			strcasecmp(ident, "DELETE") && strcasecmp(ident, "MERGE") &&
			strcasecmp(ident, "SELECT") && strcasecmp(ident, "WITH");
	}

	if (passAsIs)
	{
		memcpy(sql_out, ZSTR_VAL(sql), ZSTR_LEN(sql));
		sql_out[ZSTR_LEN(sql)] = '\0';
		*sql_out_len = ZSTR_LEN(sql);
		return 1;
	}

	char *sql_out_p = sql_out;
	memcpy(sql_out_p, start, p - start);
	sql_out_p += p - start;

	while (p < end)
	{
		start = p;
		tok = getToken(&p, end);
		switch (tok)
		{
		case ttParamMark: {
			const char* p_peek = p;
			tok = getToken(&p_peek, end);
			if (tok == ttIdent /*|| tok == ttString*/)
			{
				p = p_peek;
				++pindex;
				l = p - start;
				/* check the length of the identifier */
				/* in Firebird 4.0 it is 63 characters, in previous versions 31 bytes */
				/* + symbol ":" */
				if (l > 253) {
					return 0;
				}
				memcpy(pname, start, l);
				pname[l] = '\0';

				if (named_params) {
					zval tmp;
					ZVAL_LONG(&tmp, pindex);
					zend_hash_str_update(named_params, pname, l, &tmp);
				}

				*sql_out_p++ = '?';
			}
			else
			{
				if (strncmp(start, "?", 1)) {
					/* Execute statement preprocess SQL error */
					/* Parameter name expected */
					return 0;
				}
				++pindex;
				memcpy(sql_out_p, start, p - start);
				sql_out_p += p - start;
			}
			break;
		}
		case ttIdent:
			if (execBlock)
			{
				/* In the EXECUTE BLOCK statement, processing must be */
				/* carried out up to the keyword AS. */
				l = p - start;
				/* check the length of the identifier */
				/* in Firebird 4.0 it is 63 characters, in previous versions 31 bytes */
				if (l > 252) {
					return 0;
				}
				memcpy(ident, start, l);
				ident[l] = '\0';
				if (!strcasecmp(ident, "AS"))
				{
					memcpy(sql_out_p, start, end - start);
					sql_out_p += end - start;
					*sql_out_p = '\0';
					*sql_out_len = sql_out_p - sql_out;
					return 1;
				}
			}
			/* TODO Check this is correct? */
			ZEND_FALLTHROUGH;

		case ttWhite:
		case ttComment:
		case ttString:
		case ttOther:
			memcpy(sql_out_p, start, p - start);
			sql_out_p += p - start;
			break;

		case ttBrokenComment:
		{
			/* Execute statement preprocess SQL error */
			/* Unclosed comment found near ''@1'' */
			return 0;
		}
		break;


		case ttNone:
			/* Execute statement preprocess SQL error */
			return 0;
			break;
		}
	}
	*sql_out_p = '\0';
	*sql_out_len = sql_out_p - sql_out;
	return 1;
}

